const queue = async () => {
  if (!navigator.onLine) {
    const pending = JSON.parse(localStorage.getItem('mutationQueue') || '[]');
    pending.push({ type: 'ADD_TODO', payload: newTodo, timestamp: Date.now() });
    localStorage.setItem('mutationQueue', JSON.stringify(pending));
    return;
  }
  // Process queue when online
  const pending = JSON.parse(localStorage.getItem('mutationQueue') || '[]');
  for (const mutation of pending) {
    await axios.post('/api/todos', mutation.payload);
  }
  localStorage.removeItem('mutationQueue');
  queryClient.invalidateQueries(['todos']);
};

window.addEventListener('online', queue);
